-- Network Asset Management System - Transformer Database
-- Generated from Transformer excel.xlsx
-- Import this file in phpMyAdmin.

CREATE DATABASE IF NOT EXISTS network_asset_management
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE network_asset_management;

SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS transformer_assets;
DROP TABLE IF EXISTS cscs;
DROP TABLE IF EXISTS areas;
DROP TABLE IF EXISTS provinces;
SET FOREIGN_KEY_CHECKS=1;

CREATE TABLE provinces (
        province_id INT AUTO_INCREMENT PRIMARY KEY,
        province_name VARCHAR(100) NOT NULL UNIQUE
    ) ENGINE=InnoDB;

CREATE TABLE areas (
        area_id INT AUTO_INCREMENT PRIMARY KEY,
        province_id INT NOT NULL,
        area_name VARCHAR(100) NOT NULL,
        UNIQUE KEY uq_area (province_id, area_name),
        FOREIGN KEY (province_id) REFERENCES provinces(province_id)
    ) ENGINE=InnoDB;

CREATE TABLE cscs (
        csc_id INT AUTO_INCREMENT PRIMARY KEY,
        area_id INT NOT NULL,
        csc_name VARCHAR(100) NOT NULL,
        UNIQUE KEY uq_csc (area_id, csc_name),
        FOREIGN KEY (area_id) REFERENCES areas(area_id)
    ) ENGINE=InnoDB;

CREATE TABLE transformer_assets (
        asset_id INT AUTO_INCREMENT PRIMARY KEY,
        csc_id INT NOT NULL,
        old_sin_no VARCHAR(100),
        new_sin_no VARCHAR(100),
        substation_name VARCHAR(255) NOT NULL,
        transformer_type VARCHAR(100),
        capacity_kva DECIMAL(10,2),
        transformer_no VARCHAR(100),
        quantity INT DEFAULT 1,
        status VARCHAR(30) DEFAULT 'Active',
        latitude DECIMAL(10,7) NULL,
        longitude DECIMAL(10,7) NULL,
        remarks TEXT NULL,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
        FOREIGN KEY (csc_id) REFERENCES cscs(csc_id),
        INDEX idx_new_sin (new_sin_no),
        INDEX idx_type (transformer_type),
        INDEX idx_capacity (capacity_kva)
    ) ENGINE=InnoDB;




 Substation', 100, NULL, 0 FROM cscs WHERE csc_name='Bandarawela' LIMIT 1;
 Substation', 1000, NULL, 0 FROM cscs WHERE csc_name='Bandarawela' LIMIT 1;

-- Useful summary view for the web panel
DROP VIEW IF EXISTS v_transformer_summary;
CREATE VIEW v_transformer_summary AS
       SELECT
           p.province_name,
           a.area_name,
           c.csc_name,
           COUNT(t.asset_id) AS transformer_records,
           COALESCE(SUM(t.quantity),0) AS total_transformer_quantity,
           COALESCE(SUM(t.capacity_kva * t.quantity),0) AS total_capacity_kva
       FROM provinces p
       JOIN areas a ON a.province_id = p.province_id
       JOIN cscs c ON c.area_id = a.area_id
       LEFT JOIN transformer_assets t ON t.csc_id = c.csc_id
       GROUP BY p.province_name, a.area_name, c.csc_name;

